// Software TLB for Mario Tennis.
//
// The game maps data (e.g. segment 2 at virtual 0x02000000) and one code module (0x50000000)
// through the CPU TLB, and dereferences those virtual addresses directly. The recompiled code
// routes every memory access through mt_xlat (include/recomp.h, generated by
// tools/make_recomp_h.py); addresses outside KSEG0 land here.
#include <cstdio>
#include <cstdint>
#include <cstdlib>
#include <mutex>
#include <unordered_set>
#include "recomp.h"

namespace {
    constexpr uint32_t page_shift = 12;                       // 4 KiB granularity
    constexpr uint32_t kuseg_pages = 0x80000000u >> page_shift;
    constexpr uint32_t unmapped = 0xFFFFFFFFu;
    constexpr uint32_t trash_phys = 0x1FFFE000u;              // spare page inside the RDRAM reservation
    constexpr int tlb_entries = 32;

    uint32_t page_table[kuseg_pages];                        // virtual page -> physical page base
    bool table_initialized = false;

    struct EntryRange { uint32_t vaddr = 0, size = 0; };
    EntryRange entries[tlb_entries];

    void init_table() {
        if (!table_initialized) {
            for (auto& p : page_table) p = unmapped;
            table_initialized = true;
        }
    }

    void map_range(uint32_t vaddr, uint32_t size, uint32_t phys) {
        for (uint32_t off = 0; off < size; off += 1u << page_shift) {
            uint32_t page = (vaddr + off) >> page_shift;
            if (page < kuseg_pages) page_table[page] = (phys + off) & ~((1u << page_shift) - 1);
        }
    }

    void unmap_range(uint32_t vaddr, uint32_t size) {
        for (uint32_t off = 0; off < size; off += 1u << page_shift) {
            uint32_t page = (vaddr + off) >> page_shift;
            if (page < kuseg_pages) page_table[page] = unmapped;
        }
    }
}

extern "C" gpr mt_xlat_slow(gpr address) {
    uint32_t a = (uint32_t)address;
    // KSEG1 (uncached) aliases KSEG0.
    if ((a & 0xE0000000u) == 0xA0000000u) {
        return (gpr)(int64_t)(int32_t)(a - 0x20000000u);
    }
    if (a < 0x80000000u) {
        init_table();
        uint32_t phys = page_table[a >> page_shift];
        if (phys != unmapped) {
            return (gpr)(int64_t)(int32_t)(0x80000000u | phys | (a & ((1u << page_shift) - 1)));
        }
    }
    // Unmapped (or KSEG2/3): report once per page and redirect to a spare page instead of crashing.
    static std::mutex m;
    static std::unordered_set<uint32_t> reported;
    {
        std::lock_guard lock{ m };
        if (reported.insert(a >> page_shift).second && reported.size() < 64) {
            fprintf(stderr, "[mt] access to unmapped virtual address 0x%08X (caller %p)\n", a, __builtin_return_address(0));
        }
    }
    return (gpr)(int64_t)(int32_t)(0x80000000u | trash_phys | (a & ((1u << page_shift) - 1)));
}

// osMapTLB(index, pagemask, vaddr, evenpaddr, oddpaddr, asid): one entry maps an even and an odd
// page of (pagemask + 0x2000) / 2 bytes each; a physical address of -1 leaves that half invalid.
static uint8_t* recomp_rdram_for_logging = nullptr;  // for diagnostics without an rdram argument
extern "C" void osMapTLB_recomp(uint8_t* rdram, recomp_context* ctx) {
    init_table();
    recomp_rdram_for_logging = rdram;
    uint32_t index = (uint32_t)ctx->r4 & (tlb_entries - 1);
    uint32_t pagemask = (uint32_t)ctx->r5;
    uint32_t vaddr = (uint32_t)ctx->r6;
    uint32_t even = (uint32_t)ctx->r7;
    uint32_t odd = (uint32_t)MEM_W(0x10, ctx->r29);
    uint32_t page_size = (pagemask + 0x2000u) >> 1;

    static const bool log_tlb = std::getenv("MT_LOG_TLB") != nullptr;
    if (log_tlb) {
        fprintf(stderr, "[mt] osMapTLB(%u, mask 0x%X, vaddr 0x%08X -> 0x%08X / 0x%08X)\n", index, pagemask, vaddr, even, odd);
    }

    EntryRange& e = entries[index];
    if (e.size != 0) unmap_range(e.vaddr, e.size);   // the entry is being replaced
    e = { vaddr, page_size * 2 };

    if (even != 0xFFFFFFFFu) map_range(vaddr, page_size, even);
    if (odd != 0xFFFFFFFFu) map_range(vaddr + page_size, page_size, odd);
}

// osVirtualToPhysical (0x80033160 in the game). The runtime's version returns TLB-mapped addresses
// unchanged, but the game converts its TLB-mapped model data (0x02xxxxxx) to physical addresses
// for the RSP, so this one resolves them through the software TLB.
extern "C" void mt_osVirtualToPhysical(uint8_t* rdram, recomp_context* ctx) {
    (void)rdram;
    uint32_t a = (uint32_t)ctx->r4;
    uint32_t phys;
    if ((a & 0xC0000000u) == 0x80000000u) {
        phys = a & 0x1FFFFFFFu;  // KSEG0 / KSEG1
    }
    else {
        phys = (uint32_t)mt_xlat_slow((gpr)(int64_t)(int32_t)a) & 0x1FFFFFFFu;
    }
    ctx->r2 = (gpr)(int64_t)(int32_t)phys;
}

// Function lookups through TLB-mapped addresses (LOOKUP_FUNC in include/recomp.h).
extern "C" gpr mt_xlat_func_slow(gpr address) {
    static const bool log = std::getenv("MT_LOG_TLB_CALLS") != nullptr;
    gpr out = mt_xlat_slow(address);
    if (log) {
        static int n = 0;
        if (n++ < 200) {
            uint8_t* rdram = recomp_rdram_for_logging;
            fprintf(stderr, "[mt] call via 0x%08X -> 0x%08X (caller %p)", (uint32_t)address, (uint32_t)out, __builtin_return_address(0));
            if (rdram != nullptr) {
                fprintf(stderr, " words:");
                for (int i = 0; i < 6; i++) fprintf(stderr, " %08X", (uint32_t)MEM_W(4 * i, out));
            }
            fprintf(stderr, "\n");
        }
    }
    return out;
}
